Here are the domain objects:
```json
{
  "domain objects": [
    {
      "name": "Media Planner",
      "description": "Person who plans channels and schedules for the Advertising Campaign"
    },
    {
      "name": "Advertising Campaign",
      "description": "Coordinated set of ads targeting a specific audience",
      "attributes": [
        "Media Channel",
        "Advertisement Variation",
        "Performance Report",
        "Target Audience"
      ]
    },
    {
      "name": "Media Channel",
      "description": "Medium where ads are placed"
    },
    {
      "name": "Performance Report",
      "description": "Summary of how the Advertising Campaign performs"
    },
    {
      "name": "Target Audience",
      "description": "Group the Advertising Campaign aims to reach"
    },
    {
      "name": "Outlet",
      "description": "Media provider offering ad placement options",
      "attributes": [
        "Media Channel",
        "Placement Schedule"
      ]
    },
    {
      "name": "Placement Schedule",
      "description": "Timing of when ads appear on an Outlet"
    },
    {
      "name": "Content Creator",
      "description": "Person who designs ad content and visuals"
    },
    {
      "name": "Advertisement Variation",
      "description": "Different creative versions of an advertisement"
    },
    {
      "name": "Account Manager",
      "description": "Person who coordinates with the Advertiser and media partners"
    },
    {
      "name": "Contract Negotiation",
      "description": "Process for agreeing on terms with an Outlet"
    },
    {
      "name": "Advertiser",
      "description": "Client who owns the brand and approves ads"
    },
    {
      "name": "Campaign Analyst",
      "description": "Person who evaluates campaign data and audience behavior"
    },
    {
      "name": "Social Media Coordinator",
      "description": "Person who posts ads and manages social engagement"
    },
    {
      "name": "Posting",
      "description": "Published social media content"
    },
    {
      "name": "User Interaction",
      "description": "Engagement actions by a User on a Posting"
    },
    {
      "name": "User",
      "description": "Person interacting with posted advertisements"
    }
  ]
}
